,\n      {\n        \"chapter_number\": 2,\n        \"title\": \"重逢\",\n        \"word_count_estimate\": 3800,\n        \"chapter_synopsis\": \"林语到达集训基地，在训练馆遇见陈星。前世的陈星最后是在轮椅上，而现在站在面前的陈星鲜活美丽，却用恐惧的眼神看着她。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"训练馆，清晨\",\n            \"characters_present\": [\"林语\", \"周丽华\"],\n            \"scene_purpose\": \"建立环境，引入教练\",\n            \"core_action\": \"林语提前到达，周丽华询问她是否紧张\",\n            \"conflict_point\": \"林语用教练经验回答问题，周丽华眼神闪过疑惑\",\n            \"emotional_shift\": \"从小心翼翼隐藏到差点暴露的后怕\",\n            \"scene_outcome\": \"周丽华对林语产生兴趣\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"更衣室走廊\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"核心重逢，展示陈星异常\",\n            \"core_action\": \"林语激动叫出陈星名字，张开手臂想拥抱\",\n            \"conflict_point\": \"陈星后退避开，眼神满是戒备和恐惧\",\n            \"emotional_shift\": \"从终于见到你的狂喜到她为什么这么怕我的困惑\",\n            \"scene_outcome\": \"陈星匆匆离开，林语心中升起不祥预感\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"训练馆角落\",\n            \"characters_present\": [\"林语\", \"赵晓雨\"],\n            \"scene_purpose\": \"引入信息，暗示陈星异常\",\n            \"core_action\": \"赵晓雨热情打招呼，问起她和陈星关系\",\n            \"conflict_point\": \"赵晓雨说陈星今天怪怪的，本来很期待见到你\",\n            \"emotional_shift\": \"从困惑到警觉\",\n            \"scene_outcome\": \"林语怀疑陈星也重生了\"\n          }\n        ]\n      },\n      {\n        \"chapter_number\": 3,\n        \"title\": \"恐惧的眼神\",\n        \"word_count_estimate\": 3600,\n        \"chapter_synopsis\": \"集训开始，林语和陈星分到同一宿舍。林语试图拉近关系，陈星却保持距离。夜里林语听到陈星梦话，确认她也重生了。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"国家队宿舍双人间\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"展示宿舍生活，凸显戒备\",\n            \"core_action\": \"林语主动帮陈星整理床铺，陈星礼貌拒绝\",\n            \"conflict_point\": \"林语碰到陈星的手，陈星像被烫到一样缩回\",\n            \"emotional_shift\": \"从善意到担忧\",\n            \"scene_outcome\": \"意识到陈星的恐惧是心理创伤\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"训练馆，自由训练时间\",\n            \"characters_present\": [\"林语\", \"陈星\", \"赵晓雨\"],\n            \"scene_purpose\": \"展示陈星对林语的回避\",\n            \"core_action\": \"分组训练，陈星主动要求与赵晓雨搭档\",\n            \"conflict_point\": \"周丽华质疑分组选择，陈星借口学习动作风格\",\n            \"emotional_shift\": \"从失落到疑惑\",\n            \"scene_outcome\": \"林语观察到陈星频繁看向她\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"宿舍深夜\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"确认陈星重生\",\n            \"core_action\": \"林语被噩梦惊醒，听到陈星梦话\",\n            \"conflict_point\": \"梦话内容与前世事故吻合\",\n            \"emotional_shift\": \"从猜测到确认\",\n            \"scene_outcome\": \"林语彻夜未眠\"\n          }\n        ]\n      },\n      {\n        \"chapter_number\": 4,\n        \"title\": \"错位的时间线\",\n        \"word_count_estimate\": 3700,\n        \"chapter_synopsis\": \"林语观察陈星，发现她回避平衡木训练，做噩梦时护住腰部。林语意识到在陈星记忆中，事故是林语故意推她下去的。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"训练馆平衡木区\",\n            \"characters_present\": [\"林语\", \"陈星\", \"周丽华\"],\n            \"scene_purpose\": \"展示陈星对平衡木的恐惧\",\n            \"core_action\": \"陈星上平衡木时脸色苍白动作僵硬\",\n            \"conflict_point\": \"周丽华指出动作变形，陈星解释身体不适\",\n            \"emotional_shift\": \"从观察到推测\",\n            \"scene_outcome\": \"林语意识到恐惧有针对性\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"宿舍午休\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"揭示心理状态\",\n            \"core_action\": \"林语给陈星递水，陈星手指发抖水洒床上\",\n            \"conflict_point\": \"陈星擦拭水渍露出手腕旧疤\",\n            \"emotional_shift\": \"从担忧到心疼\",\n            \"scene_outcome\": \"意识到陈星带着创伤记忆\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"宿舍深夜\",\n            \"characters_present\": [\"林语\"],\n            \"scene_purpose\": \"拼凑记忆版本\",\n            \"core_action\": \"林语画时间线对比记忆\",\n            \"conflict_point\": \"推断出陈星记忆：林语推她下平衡木\",\n            \"emotional_shift\": \"从困惑到震惊到理解\",\n            \"scene_outcome\": \"决定用行动证明善意\"\n          }\n        ]\n      },\n      {\n        \"chapter_number\": 5,\n        \"title\": \"赎罪者的温柔\",\n        \"word_count_estimate\": 3600,\n        \"chapter_synopsis\": \"林语开始用行动补偿陈星：帮她占训练位置、准备她喜欢的食物、在她噩梦时守夜。陈星表面接受，内心却更加困惑——前世伤害她的人为什么突然变得温柔。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"训练馆清晨\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"展示林语的主动示好\",\n            \"core_action\": \"林语提前到馆帮陈星占好位置，准备好她喜欢的运动饮料\",\n            \"conflict_point\": \"陈星看着饮料眼神复杂，前世她在瘫痪后才爱上这个口味\",\n            \"emotional_shift\": \"从戒备到困惑\",\n            \"scene_outcome\": \"陈星默默接受但心中疑虑更深\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"食堂午餐\",\n            \"characters_present\": [\"林语\", \"陈星\", \"赵晓雨\"],\n            \"scene_purpose\": \"通过日常互动展示关系变化\",\n            \"core_action\": \"林语特意为陈星打她爱吃的菜，动作自然得像做过千百次\",\n            \"conflict_point\": \"赵晓雨开玩笑说林语像陈星的保姆，陈星勉强笑了笑\",\n            \"emotional_shift\": \"从尴尬到更深的困惑\",\n            \"scene_outcome\": \"陈星开始怀疑林语知道些什么\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"宿舍深夜\",\n            \"characters_present\": [\"林语\", \"陈星\"],\n            \"scene_purpose\": \"展示林语的守护\",\n            \"core_action\": \"陈星再次做噩梦惊醒，发现林语坐在床边守着她\",\n            \"conflict_point\": \"林语轻声说我在，别怕，语气中带着陈星听不懂的悲伤\",\n            \"emotional_shift\": \"从恐惧到复杂的情感\",\n            \"scene_outcome\": \"陈星在矛盾中再次入睡，林语彻夜守护\"\n          }\n        ]\n      },\n      {\n        \"chapter_number\": 6,\n        \"title\": \"复仇者的挣扎\",\n        \"word_count_estimate\": 3700,\n        \"chapter_synopsis\": \"陈星内心剧烈挣扎。她重生的目标是远离林语、保护自己，但林语的温柔让她动摇。她试图说服自己这只是伪装，却在林语的眼神中看到了前世的愧疚——那不是一个凶手会有的眼神。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"训练馆角落\",\n            \"characters_present\": [\"陈星\"],\n            \"scene_purpose\": \"展示陈星内心独白\",\n            \"core_action\": \"陈星独自坐在角落，手握着腿部，回忆前世瘫痪后的痛苦\",\n            \"conflict_point\": \"她想起前世林语在病床前的眼泪，那种悲伤不像装的\",\n            \"emotional_shift\": \"从仇恨的坚定到记忆的动摇\",\n            \"scene_outcome\": \"陈星决定试探林语\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"训练馆\",\n            \"characters_present\": [\"林语\", \"陈星\", \"周丽华\"],\n            \"scene_purpose\": \"陈星主动接近试探\",\n            \"core_action\": \"陈星主动邀请林语搭档训练，观察她的反应\",\n            \"conflict_point\": \"林语眼中闪过惊喜和谨慎，接受邀请时手指微微颤抖\",\n            \"emotional_shift\": \"从试探到发现异常\",\n            \"scene_outcome\": \"训练过程中两人配合默契，陈星感到一种奇怪的熟悉感\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"宿舍\",\n            \"characters_present\": [\"陈星\"],\n            \"scene_purpose\": \"陈星回忆前世片段\",\n            \"core_action\": \"陈星躺在床上回想前世事故瞬间，记忆变得模糊\",\n            \"conflict_point\": \"她隐约记得当时林语的表情是惊恐而非恶意\",\n            \"emotional_shift\": \"从确定的仇恨到开始怀疑\",\n            \"scene_outcome\": \"陈星决定继续观察，但复仇的决心开始动摇\"\n          }\n        ]\n      },\n      {\n        \"chapter_number\": 7,\n        \"title\": \"默契\",\n        \"word_count_estimate\": 3800,\n        \"chapter_synopsis\": \"林语和陈星的配合越来越好，达到了前世作为搭档的默契水平。其他队员惊讶于她们的同步率，陈星却在默契中感到恐惧——前世她们从未如此亲密，为什么这一世的林语如此了解她。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"训练馆\",\n            \"characters_present\": [\"林